// bindDataToMap binds data to a map destination. Only limited map types are
// supported: map[string][]string, map[string]string (binds first value from
// data slice) and map[string]interface{}.
func (b *DefaultBinder) bindDataToMap(destination interface{}, data map[string][]string, tag ...string) error {
	if destination == nil || len(data) == 0 {
		return nil
	}
	val := reflect.ValueOf(destination).Elem()
	typ := val.Type()

	// map target is not pointer, but map type
	if typ.Kind() != reflect.Map {
		return errors.New("binding element must be a map")
	}

	for k, v := range data {
		// if the map is a map[string][]string, we can bind the whole slice
		// if the map is a map[string]string, we bind the first value
		if typ.Elem().Kind() == reflect.Slice {
			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
		} else {
			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
		}
	}
	return nil
}

