func TestZZGzipFullStack(t *testing.T) {
	for _, h := range []string{"nil", "emptywrite", "emptystring"} {
		e := echo.New()
		e.Use(Gzip())
		switch h {
		case "nil":
			e.GET("/", func(c echo.Context) error { return nil })
		case "emptywrite":
			e.GET("/", func(c echo.Context) error { c.Response().Write([]byte{}); return nil })
		case "emptystring":
			e.GET("/", func(c echo.Context) error { return c.String(200, "") })
		}
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		t.Logf("%-12s code=%d len=%d CE=%q CL=%q body=%q", h, rec.Code, rec.Body.Len(),
			rec.Header().Get(echo.HeaderContentEncoding), rec.Header().Get("Content-Length"), rec.Body.Bytes())
		if rec.Body.Len() > 0 {
			r, err := gzip.NewReader(rec.Body)
			if err == nil {
				b, _ := ioutil.ReadAll(r)
				t.Logf("   gunzip -> %q", b)
			} else {
				t.Logf("   gunzip err: %v", err)
			}
		}
	}
}
